// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address caller, bool access) public {
        vm.assume(caller != address(0) && caller != address(this));
        // Drive through adjustAdminAccess
        vm.prank(address(this));
        c.adjustAdminAccess(caller, access);

        bytes4 interfaceId = 0x0e89341c; // IERC1155MetadataURI interface ID
        assertTrue(c.supportsInterface(interfaceId));
    }
}

